    double y = 0.f;
    Node* parent = nullptr;
    int index_ = -1;
};

struct Graph {
    std::vector<Node> nodes;
    std::vector<std::vector<int>> adjacency_list;
};

float heuristic(Node* a, Node* b) {
    return std::sqrt(std::pow(a->x - b->x, 2) + std::pow(a->y - b->y, 2));
}

std::vector<Node> a_star_search(Graph& graph, int start_idx, int end_idx) {
    if (start_idx < 0 || start_idx >= graph.nodes.size() || 
        end_idx < 0 || end_idx >= graph.nodes.size() || 
        start_idx == end_idx) {
        return {};
    }

    auto compare = [](const std::pair<float, Node*>& a, const std::pair<float, Node*>& b) {
        return a.first > b.first;
    };
    std::priority_queue<
        std::pair<float, Node*>, 
        std::vector<std::pair<float, Node*>>, 
        decltype(compare)
    > open_set(compare);

    std::unordered_map<Node*, float> g_score;
    std::unordered_map<Node*, float> f_score;
    std::unordered_map<Node*, Node*> came_from;

    for (auto& node : graph.nodes) {
