        Node* current = open_set.top().second;
        open_set.pop();

        if (current == end_node) {
            std::vector<Node> path;
            while (current != nullptr) {
                path.push_back(*current);
                current = current->parent;
            }
            std::reverse(path.begin(), path.end());
            return path;
        }

        for (int neighbor_idx : graph.adjacency_list[current->index_]) {
            Node* neighbor = &graph.nodes[neighbor_idx];
            float tentative_g_score = g_score[current] + 1; // Assuming uniform edge cost

            if (tentative_g_score < g_score[neighbor]) {
                came_from[neighbor] = current;
                g_score[neighbor] = tentative_g_score;
                f_score[neighbor] = g_score[neighbor] + heuristic(neighbor, end_node);
                open_set.push({f_score[neighbor], neighbor});
            }
        }
    }

    return {}; // No path found
}"}

